#!/usr/bin/env python3
"""Minimal kernels for the scoreboard-index instability under `CUBIT_SB_SHARE=1 CUBIT_RB_EARLY=32`, one innocent edit
per file, for `tests/fixtures/sb_long_keep/` (session RA-1, 2026-11-10; the rule they test: `CUBIT_SB_LONG_KEEP`).

One shape (~320 instructions): a PREFETCH -- four global loads into R40..R43 through one address temp that is
recomputed for every load, as a gather does; issued first and read at the very end, more than `CUBIT_SB_LONG` (256)
instructions later -- and in between 32 ROUNDS of a compute phase: four shared-memory loads issued together and
consumed together, i.e. four short scoreboard uses alive at a time. With the prefetch on the top two scoreboards
that is six: in the base nothing shares and nothing waits for the prefetch before its readers. Every other file is
the base plus ONE edit of the kind that moved or drained the gather of the attention kernel:

  edit_base              the base: four loads per round, 40 quiet instructions behind the prefetch
  edit_no_quiet          the rounds start right behind the prefetch, while the address latch of its last load is held
  edit_one_more_load     one round (the 21st) has a fifth load                       "adding one load to the loop"
  edit_late_latch_load   one round has a load through its own address register, and a temp behind it
  edit_renumbered_temp   the same, the temp renumbered onto that address register    "a renumbering by cubit ra"

    python3 tests/fixtures/sb_long_keep/gen_edits.py tests/fixtures/sb_long_keep
        -> <name>.sass for every edit (deterministic: the files are generated, not edited; tests/sb_long_keep.rs pins
           what the colouring does to each of them)
"""
import sys

ROUNDS = 32            # 32 rounds x >= 8 instructions between the prefetch and its readers (> CUBIT_SB_LONG = 256)


def acc(reg):
    """One reader: R30 += 3 * reg (an IMAD chain: no pair of the kernel sits below the dependency verifier's default)."""
    return f"    IMAD R30, {reg}, 0x3, R30 ;"


def kernel(name, what, sixth_round=None, branch_round=None, long2=None, recycle_round=None, renum_round=None, temp="R44", addr2="R33", quiet=True, one_addr=True, release=False, latch_round=None):
    L = []
    A = L.append
    A(f"// tests/fixtures/sb_long_keep/{name}.sass -- {what}")
    A("// A minimal prefetch kernel (session RA-1, 2026-11-10); generated by gen_edits.py next to this file -- do not edit.")
    A("// The prefetch = the four `LDG.E R40..R43`; its first reader = `IMAD R30, R40, 0x3, R30` at the end.")
    A("// Build: CUBIT_SB_SHARE=1 CUBIT_RB_EARLY=32 cubit asm (+ CUBIT_SB_LONG_KEEP=1); see tests/sb_long_keep.rs.")
    A(".entry sbk")
    A("    .reg R0-R61")
    A("    .param u64 out")
    A("    .param u64 inp")
    A("    LDC.64 R2, c[0x0][0x380] ;")                    # the two constant loads apart: one LDC port
    A("    S2R R0, SR_TID.X ;")
    A("    LDCU.64 UR4, c[0x0][0x358] ;")
    A("    LDC.64 R4, c[0x0][0x388] ;")
    A("    IMAD.WIDE.U32 R2, PT, R0, 0x40, R2 ;")
    A("    IMAD.WIDE.U32 R4, PT, R0, 0x40, R4 ;")
    A("    IMAD R1, R0, 0x400, RZ ;")
    A("    ISETP.NE.AND P0, PT, R0, RZ, PT ;")
    if latch_round is not None:
        A("    MOV R45, 0x7 ;")
    if long2 == "front":                                   # a second long load in front of the prefetch
        A("    IMAD.WIDE.U32 R36, PT, R0, 0x10, R4 ;")
        A("    LDG.E R48, desc[UR4][R36.64] ;")
    # ---- the prefetch: 4 global loads, 4 address streams
    for g in range(4):
        a = 6 if one_addr else 6 + 2 * g                   # one address temp, recomputed for every load (as a gather does)
        A(f"    IMAD.WIDE.U32 R{a}, PT, R0, {4 * (g + 1):#x}, R4 ;")
        A(f"    LDG.E R{40 + g}, desc[UR4][R{a}.64] ;")
    if release:                                            # the address temp is rewritten: the last load's address latch is released
        A("    IMAD.WIDE.U32 R6, PT, R0, 0x40, R4 ;")
    if long2 == "behind":
        A("    IMAD.WIDE.U32 R36, PT, R0, 0x10, R4 ;")
        A("    LDG.E R48, desc[UR4][R36.64] ;")
    if latch_round is not None:                            # a store behind the prefetch; its data register is next written
        A("    STS [R1+0x300], R45 ;")                     # in round `latch_round`, more than CUBIT_SB_LONG instructions later
    A("    MOV R30, RZ ;")
    if quiet:                                              # 40 instructions with nothing in flight but the prefetch: the read
        for _ in range(40):                                # barriers of its loads (their address latches) are released here
            A("    IADD3 R30, PT, PT, R30, 0x1, RZ ;")
    # ---- the compute: rounds of shared loads issued together, consumed together
    for r in range(ROUNDS):
        n = 5 if r == sixth_round else 4
        for k in range(n):
            A(f"    LDS R{16 + k}, [R1+{0x80 * k:#x}] ;")
        if r == latch_round:                               # the store's data register is rewritten: the write waits for the latch
            A("    MOV R45, 0x9 ;")
        if r == recycle_round:                             # a store whose data register is rewritten right behind it
            A("    STS [R1+0x300], R30 ;")
        if r == renum_round:                               # a late-latching load through its own address register ...
            A(f"    IADD3 {addr2}, PT, PT, R1, 0x380, RZ ;")
            A(f"    LDS R50, [{addr2}] ;")
        for k in range(n):
            if r == branch_round and k == 0:
                continue                                   # this round's first load is read in the arm below
            A(acc(f"R{16 + k}"))
        if r == renum_round:                               # ... and a temp that a renumbering may put on that register
            A(f"    IADD3 {temp}, PT, PT, R30, 0x1, RZ ;")
            A(acc(temp))
            A(acc("R50"))
        if r == branch_round:
            A(f"    @P0 BRA arm_skip_{r} ;")
            A(acc("R16"))
            A(f"arm_skip_{r}:")
    # ---- the readers of the prefetch
    for g in range(4):
        A(acc(f"R{40 + g}"))
    if long2:
        A(acc("R48"))
    A("    STG.E desc[UR4][R2.64], R30 ;")
    A("    EXIT ;")
    A(".endentry")
    return "\n".join(L) + "\n"


EDITS = {
    "edit_base": ("the base kernel: four shared loads per round, 40 quiet instructions behind the prefetch", dict()),
    "edit_no_quiet": ("the base with the compute starting right behind the prefetch", dict(quiet=False)),
    "edit_one_more_load": ("the base with a fifth load in one round", dict(sixth_round=20)),
    "edit_late_latch_load": ("the base with a load through its own address register and a temp behind it", dict(renum_round=20)),
    "edit_renumbered_temp": ("edit_late_latch_load with the temp renumbered onto the load's address register", dict(renum_round=20, temp="R33")),
}
# Tried and left out -- no wait on the prefetch's scoreboards in this toy, with or without the switch: a second long load
# in front of / behind the prefetch (long2), a reader in a branch arm (branch_round), a store whose data register is
# rewritten right behind it (recycle_round) or late in the compute (latch_round). `kernel()` still takes them.

if __name__ == "__main__":
    out = sys.argv[1]
    for name, (what, kw) in EDITS.items():
        open(f"{out}/{name}.sass", "w").write(kernel(name, what, **kw))
    print(" ".join(EDITS))
